import * as React from 'react';
import {
  StyleSheet,
  View,
  Text,
  TouchableOpacity,
  ActivityIndicator
} from 'react-native';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import { Scale } from '../../utils/size';
import { Colors } from '../../Assets/Colors';

const Buttons = ({ navigation, style, title, styleTitle, onPress, switchAccount,disabled, loading}) => {
  return (
    <TouchableOpacity
      disabled ={disabled ? disabled : false}
      onPress={onPress}>
      <View style={[styles.viewButton, {backgroundColor : switchAccount ? Colors.primaryColorHub : Colors.primaryColor}, style]}>
        <Text style={[styles.text60012, { color: Colors.white, textAlign:'center' }, styleTitle]}>{loading && <ActivityIndicator />}{ !loading && title}</Text>
      </View>
    </TouchableOpacity>
  );
}

const styles = StyleSheet.create({
  viewButton:{
    height: Scale(40),
    marginTop: Scale(8),
    borderRadius: Scale(10),
    borderColor: "black", //button background/border color
    overflow: "hidden",
    marginBottom: Scale(10),
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: Colors.primaryColor
  },
  text60012:{ color: Colors.black, fontWeight: '600', fontSize: Scale(12) },
});
export default Buttons;