// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  Image,
  ScrollView,
  SafeAreaView,
  Share
} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import Toolbar from '../../../Component/Toolbar';
import { Metrics, Scale } from '../../../utils/size';
import TextInput from '../../../Component/TextInput';
import Buttons from '../../../Component/Button';
import QRCode from 'react-native-qrcode-svg';
import { Constants } from '../../../utils/Constans';
import { getData, removeData, storeData } from '../../../utils/Storage';
import {JSONAxioGet, JSONAxioPostFile } from '../../../utils/services/JsonService';
import { getURL, postURL } from '../../../utils/services/API';
import PopUp from '../../../Component/popUp';
import { Routers } from '../../../utils/Routers';
import Loading from '../../../Component/loading';

const KodeReferal = ({route, navigation }) => {
  let [switchAccount, setswitchAccount] = useState(false);
  let [codeReferal, setCodeReferal] = useState("-");
  let [urlReferal, setURLReferal] = useState("-");
  let [noHp, setNoHp] = useState(0);
  let [dataUser, setDataUser] = useState(null);
  let [inputCodeReferal, setInputCodeReferal] = useState("");
  let [kodeReferalError, setKodeReferalError] = useState(null);
  let [token, setToken] = useState(null);
  let [contentWarning, setContentWarning] = useState(null);
  let [warning, setWarning] = useState(false);
  let [loading, setLoading] = useState(false);
  let [userRole, setUserRole] = useState(null);
  let [dataProfile,setDataProfilr] = useState(null)
    useEffect(() => {
      getData(Constants.SESSION_HUB).then(res => {
        if (res){
          setUserRole(JSON.parse(res).userRole);
          setswitchAccount(res ? true :  false);
        }
        
        getdata();
      });
    }, [route.params,codeReferal]);



    const share = async (toko) => {
      console.log(toko)
      const url = toko? dataProfile?.linkShope : urlReferal;
      const title = toko ? "Promosikan Toko": "Link Referal";
      const message = toko ? "Temukan produk berkualitas dengan harga terjangkau di toko kami! " + dataProfile?.linkShope : "Silakan melakukan pendaftaran melalui link berikut : " + dataProfile?.linkReferal;
    
      const options = {
        title,
        url,
        message,
      };
      try {
          await Share.share(options);
      } catch (error) {
          alert(error.message);
      }
  };



  

  const goBack =(item)=>{
    navigation.goBack()
  }

  const getdata = () => {
  getData(Constants.SESSION_USER_PROFILE).then(res => {
    setDataUser(res)
    console.log("<<<dasdasd>>>");
    console.log((res.result?.linkReferal != "" ? res.result?.linkReferal : "-"));
    console.log("<<<dasdasd>>>");
    getDataProfile(res.result.token)
    setCodeReferal(res.result?.kodeReferal != "" ? res.result?.kodeReferal : "-");
    setURLReferal(res.result?.linkReferal != "" ? res.result?.linkReferal : "-");
    setToken(res.result.token);
    setNoHp(res.result.hp)
   })
  }

  const onCreatedCode = (params,token) => {

    var isError = false

    setKodeReferalError(null)

    if (null == inputCodeReferal || inputCodeReferal == "" || inputCodeReferal == "-") {
      isError = true;
      setKodeReferalError("Silakan masukan kode referal anda")
    }

    if (!isError){
      cretedCodeReferal()
    }

  }


   const cretedCodeReferal = () => {
      var params ={
        userId: noHp,
        requestId: inputCodeReferal
      }
      setLoading(true);
    JSONAxioPostFile(postURL('created_referal'), params, token)
      .then(respone => {
        const response = respone.data;
        setLoading(false);
        if (response.statusCode != 1) {
          cekError(response.statusCode,  response.message);
        } else {
          cekError(response.statusCode,  response.message);

          dataUser.result.kodeReferal = inputCodeReferal;
          dataUser.result.linkReferal = response?.result?.linkReferal;
          setCodeReferal(inputCodeReferal);
          setURLReferal(response?.result?.linkReferal)
          storeData(Constants.SESSION_USER_PROFILE, dataUser);
        }
      })
      .catch(error => {
        setLoading(false);
        const err = error.toJSON().message;
        cekError(err);
      });
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
        setContentWarning({
          title: "Oooops !!",
          desc: errorMessage,
          titleButton: "Login Kembali",
          statusCode: statusCode
        })
    } else if (statusCode == 1) {
      setContentWarning({
        title: "Yeyy !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }
  
  const actionButton = (statusCode) => {
    setWarning(false);
    setContentWarning(null)
    if (contentWarning?.statusCode == 401 || contentWarning?.statusCode == 400) {
      removeData(Constants.SESSION_USER_PROFILE).then(() => {
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: Routers.MAIN_PAGE }] });
        });
      });
    } 
    
  }

  const getDataProfile = (token) => {
    var param = null
    setLoading(true);
    JSONAxioGet(getURL('api_get_profile', param), null, token)
      .then(respone => {
        const response = respone?.data;
        setLoading(false);

        if (response?.statusCode == 1) {

         console.log(JSON.stringify(response.result))
          setDataProfilr(response.result)

        } else {
          setLoading(false);

          cekError(response.statusCode, response.message);

        }
      })
      .catch(error => {
        console.log("error")
        console.log(error)
        // setLoading(false);
        cekError(2, null);

      });
  }


  return (
    <SafeAreaView style={{ flex: 1, }}>
      <View style={{ flex: 1, backgroundColor: Colors.white }}>

        <Toolbar
        switchAccount ={switchAccount}
        onPress={goBack}
        title={'Kode Referal'} />


        <Text style={[styles.text400,{marginVertical: Scale(16), marginHorizontal: Scale(16)}]}>{'Bagikan link Referal untuk mendapatkan'} {<Text style={[styles.text400,{marginVertical: Scale(16), marginHorizontal: Scale(16), color:switchAccount ? Colors.primaryColorHub :Colors.primaryColor}]}>{'Poin Belanja'}</Text>} {'dari setiap pembelanjaan teman yang anda Refrensikan'}</Text>

        <View style={{height: Scale(1), backgroundColor: Colors.gray, marginVertical: Scale(8), marginHorizontal: Scale(16)}}/>
        <ScrollView>
          <View style={{ flex: 1 }}>

            <View style={{ marginTop: Scale(18), justifyContent: 'center', alignItems: 'center' }}>
             {(urlReferal != "-") && <QRCode
                size={Metrics.screenWidth - Scale(180)}
                value= {urlReferal}
              />}

              {(null == urlReferal || urlReferal == "" || urlReferal == "-") && <View
                style={{ width: '90%' }}>

                <TextInput

                  onChange={value => {
                    setInputCodeReferal(value);
                  }}
                  // icon={} 
                  value={inputCodeReferal}
                  placeholder={'Masukan kode referal'}
                  //  onPress
                  title={'Buat Kode Referal'}
                  error={kodeReferalError}
                  editable={!loading}
                />

                <Buttons
                  // loading={loading}
                  // disabled={loading}
                  style={{ marginTop: Scale(20), backgroundColor: loading ? Colors.greenWhite : Colors.primaryColor, marginHorizontal: Scale(8) }}
                  onPress={() => onCreatedCode()}
                  title={'Buat Kode'} />
              </View>}
            </View>

            {(urlReferal != "-") && <View style={{ marginTop: Scale(20) }}>
              <Text style={[styles.text400, { marginVertical: Scale(8), marginHorizontal: Scale(20) }]}>{'Kode Referal Saya'}</Text>
              <View style={{ flexDirection: 'row', height: Scale(50), backgroundColor: Colors.gray, borderRadius: Scale(20), marginHorizontal: Scale(16), alignItems: 'center' }}>
                <View style={{ flex: 1 }}>
                  <Text style={[styles.text400, { color: Colors.txtGray, marginHorizontal: Scale(16) }]}>{codeReferal}</Text>
                </View>

                <View style={{ flex: 0.2, justifyContent: 'center', alignItems: 'center' }}>
                  <TouchableOpacity
                    onPress={() => share(false)}>
                    <View style={{ alignItems: 'center', justifyContent: 'center' }}>
                      <Image
                        style={{ height: Scale(18), width: Scale(18), tintColor: Colors.primaryColor }}
                        source={getIcon('ic_share')}
                        resizeMode='contain' />
                    </View>
                  </TouchableOpacity>
                </View>
              </View>
            </View>}

            {dataProfile?.linkShope && <Buttons
                  onPress={() => share(true)}
                  style={{ margin: Scale(24), marginTop: Scale(0), borderRadius: Scale(8), padding: Scale(8), height: Scale(40),  marginTop: Scale(18), backgroundColor: (switchAccount ? Colors.primaryColorHub : Colors.primaryColor) }}
                  title={"Promosikan Toko Anda"} />}

            <View style={{justifyContent: 'center', alignItems:'center', marginVertical: Scale(18)}}>
              <Image
                style={{ height: Scale(111), width: Scale(332) }}
                source={getIcon(switchAccount ? 'bg_howto_invite_hub' : 'bg_howto_invite')}
                resizeMode='contain' />
            </View>

          </View>
        </ScrollView>

        <Loading
          visible={loading}/>
        <PopUp
          visible={warning}
          onPressButton={() => { actionButton() }}
          title={contentWarning?.title}
          desc={contentWarning?.desc}
          titleButton={contentWarning?.titleButton} />
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
  imgRow: { height: Scale(90), width: Scale(90) },
  text400: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
});
export default KodeReferal;