// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  Image,
  ScrollView,
  SafeAreaView,
  RefreshControl
} from 'react-native';
import { Colors } from '../../Assets/Colors';
import { getIcon } from '../../Assets/Icon';
import Toolbar from '../../Component/Toolbar';
import { Scale } from '../../utils/size';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import Buttons from '../../Component/Button';
import { Routers } from '../../utils/Routers';
import { getURL,postURL, deleteURL } from '../../utils/services/API';
import { Constants } from '../../utils/Constans';
import { getData } from '../../utils/Storage';
import { JSONAxioGet,JSONAxioDelete } from '../../utils/services/JsonService';

const MethodeSendScreen = ({ navigation }) => {

  let [dataHub, setHub] = useState([]);

  let [expedisi, setExpedisi] = useState([]);

  let [ojekOnline, setOjekOnline] = useState([]);
  let [token, setToken] = useState(0)
  let [loading, setLoading] = useState(false)


  useEffect(() => {
    getdata()

  }, [token]);


  const selectSendBy =(item)=>{
    navigation.navigate(Routers.CONFIRMATION_ORDER_PAGE, {sendBy : item})
  }

  const goBack =(item)=>{
    navigation.goBack()
  }

  const getdata = () => {
    getData(Constants.SESSION_USER_PROFILE).then(res => {
      
      setToken(res.result.token)
      getListTypeDelivery();
     })
  }

  const getListTypeDelivery = (params) => {
    setLoading(true)
    // setDataProv([])
    JSONAxioGet(getURL('api-list-type-delivery', null), null, token)
    .then(respone => {
      setLoading(false);
      
      const response = respone.data;
      if (response.statusCode == 1) {
        var hubArr = [];
        response?.result?.byhub.map((item, i) => {
          if (item.delivery_code == "byhub") {
            var items = { delivery_code: "byhub", name: 'Dikirim Oleh Hub', icon: 'ic_send_hub', height: Scale(20), width: Scale(50) }
            hubArr.push(items);
          }
        })
        setHub(hubArr)

        var expedisiArr = [];
        response?.result?.ekspedisi.map((item, i) => {
          if (item.delivery_code == "jne") {
            var items = { delivery_code: "jne", name: 'Dikirim Oleh JNE', icon: 'ic_jne', height: Scale(20), width: Scale(50) }
            expedisiArr.push(items)
          }
          if (item.delivery_code == "jnt") {
            expedisiArr.push({ delivery_code: "jnt", name: 'Dikirim Oleh JNT', icon: 'ic_jnt', height: Scale(20), width: Scale(50) })
          }
          if (item.delivery_code == "sicepat") {
            expedisiArr.push({delivery_code: "sicepat", name: 'Dikirim Oleh SI Cepat', icon: 'ic_sicepat', height: Scale(20), width: Scale(60) })
          }
        })
        setExpedisi(expedisiArr)

        var ojekOnlineArr = [];
        response?.result?.kurirOnline.map((item, i) => {
          if (item.delivery_code == "gojek") {
            var items = { delivery_code: "gojek",name: 'Dikirim Oleh Gojek', icon: 'ic_gojek', height: Scale(20), width: Scale(50) }
            ojekOnlineArr.push(items)
          }
          if (item.delivery_code == "grab") {
            ojekOnlineArr.push({ delivery_code: "grab",name: 'Dikirim Oleh Grab', icon: 'ic_grap', height: Scale(20), width: Scale(50) })
          }
          if (item.delivery_code == "maxim") {
            ojekOnlineArr.push({ delivery_code: "maxim",name: 'Dikirim Oleh Maximm', icon: 'ic_maxim', height: Scale(20), width: Scale(60) })
          }
        })
        setOjekOnline(ojekOnlineArr)
      } else {
       
      }
    })
    .catch(error => {
      setLoading(false);
      console.log("error")
      console.log(error)
    });
  }


  return (
    <SafeAreaView style={{ flex: 1, }}>
      <View style={{ flex: 1, backgroundColor: Colors.white }}>

        <Toolbar
          onPress={goBack}
          title={'Metode Pengiriman'} /> 

          <ScrollView
           refreshControl={
            <RefreshControl refreshing={loading} onRefresh={getListTypeDelivery} />
          }>
            <View style={{flex:1}}>
              {
                dataHub.map((item, i) => (
                  <View style={{ marginHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2), }}>
                    <TouchableOpacity
                      onPress={() => selectSendBy(item)}>
                      <View style={{}}>
                        <View style={{ flexDirection: 'row' }}>
                          <View style={{ flex: 1 }}>
                            <Text style={{ color: Colors.black, fontWeight: '400' }}>{item.name}</Text>
                          </View>
                          <View style={{ flex: 0.2, alignItems: 'flex-end' }}>
                            <Image
                              style={{ height: item.height, width: item.width, marginHorizontal: Scale(8) }}
                              source={getIcon(item.icon)}
                              resizeMode='contain' />
                          </View>
                        </View>
                      </View>
                    </TouchableOpacity>
                  </View>
                ))
            }
            {expedisi.length > 0 && <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
              <Text style={{ color: Colors.black, fontWeight: '600', fontSize: Scale(14) }}>{"Expedisi"}</Text>
            </View>}

            {
                expedisi.map((item, i) => (
                  <View style={{ marginHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2)}}>
                    <TouchableOpacity
                      onPress={() => selectSendBy(item)}>
                      <View style={{}}>
                        <View style={{ flexDirection: 'row' }}>
                          <View style={{ flex: 1 }}>
                            <Text style={{ color: Colors.black, fontWeight: '400' }}>{item.name}</Text>
                          </View>
                          <View style={{ flex: 0.2, alignItems: 'flex-end' }}>
                            <Image
                              style={{ height: item.height, width: item.width, marginHorizontal: Scale(8) }}
                              source={getIcon(item.icon)} 
                              resizeMode='contain'/>
                          </View>
                        </View>
                      </View>
                    </TouchableOpacity>
                  </View>
                ))
            }

            {ojekOnline.length > 0 && <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
              <Text style={{ color: Colors.black, fontWeight: '600', fontSize: Scale(14) }}>{"Ojek Online"}</Text>
            </View>}

            {
                ojekOnline.map((item, i) => (
                  <View style={{ marginHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2)}}>
                    <TouchableOpacity
                      onPress={() => selectSendBy(item)}>
                      <View style={{}}>
                        <View style={{ flexDirection: 'row' }}>
                          <View style={{ flex: 1 }}>
                            <Text style={{ color: Colors.black, fontWeight: '400' }}>{item.name}</Text>
                          </View>
                          <View style={{ flex: 0.2, alignItems: 'flex-end' }}>
                            <Image
                              style={{ height: item.height, width: item.width, marginHorizontal: Scale(8) }}
                              source={getIcon(item.icon)} 
                              resizeMode='contain'/>
                          </View>
                        </View>
                      </View>
                    </TouchableOpacity>
                  </View>
                ))
            }
            </View>
          </ScrollView>

          

          

        </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
export default MethodeSendScreen;