// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useState, useEffect }  from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  Image,
  View,
  Text,
  PermissionsAndroid,
  AsyncStorage
} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import Buttons from '../../../Component/Button';
import TextInput from '../../../Component/TextInput';
import { Scale } from '../../../utils/size';
import { storeData } from '../../../utils/Storage';
import { Constants } from '../../../utils/Constans';
import { Routers } from '../../../utils/Routers';
import { JSONAxioPostFile } from '../../../utils/services/JsonService';
import { postURL } from '../../../utils/services/API';
import GetLocation from 'react-native-get-location'
import { getDeviceId, getSystemVersion, getBrand } from 'react-native-device-info';
import uuid from 'react-native-uuid';
const Login = ({ onPressTab, navigation }) => {
  let [activeLogin, setActiveLogin] = useState(true);
  let [activeRegister, setActiveRegister] = useState(false);
  let [activeEye, setActiveEye] = useState(true);
  let [loading, setLoading] = useState(false);
  let [email, setEmail] = useState(null);
  let [password, setPassword] = useState(null);
  let [location, setLocation] = useState(null);

  let [emailError, setEmailError] = useState(null);
  let [passwordError, setPasswordError] = useState(null);

  useEffect(() => {
    checkPermision();
  }, []);

  const checkPermision = async () => {
    try {
      const granted =  await PermissionsAndroid.check( PermissionsAndroid.PERMISSIONS.ACCESS_FINE_LOCATION );

      if (granted) {
        GetLocation.getCurrentPosition({
          enableHighAccuracy: true,
          timeout: 60000,
        })
          .then(location => {
            setLocation(location)
          })
          .catch(error => {
            const { code, message } = error;
            console.warn(code, message);
          })

      } 
      else {
        const granted = await PermissionsAndroid.request(
          PermissionsAndroid.PERMISSIONS.ACCESS_FINE_LOCATION
        )
      }
    } catch (err) {
      console.warn(err)
    }
  }

  const onPressLogin =()=>{

    var isError = false;
    setEmailError(null);
    setPasswordError(null);

    if (email == '' || null==email){
        setEmailError("Harap masukan Nomor Hp");
        isError = true;
    }

    if (password == '' || null==password){
      setPasswordError("Harap masukan password");
      isError = true;
  }
  
  if (!isError){
    onSubmitedLogin();
  }
    
    
  }
  

  const onSubmitedLogin = () =>{

    let brand = getBrand();
    let systemVersion = getSystemVersion();
    let idDevice = uuid.v4();
    var param = {
      fuserid:email,
      fpassword:password,
      idDevice :idDevice,
      latitude : location?.latitude,
      longitude: location?.longitude,
      os_version: brand+"_android_"+systemVersion
    }

    setLoading(true);

    JSONAxioPostFile(postURL('login'), param, null)
    .then(respone => {
      const response = respone.data;
      setLoading(false);
      if (response.statusCode > 1) {
        setEmailError(response.message);
        setPasswordError(response.message)
      } else {
        storeData(Constants.SESSION_USER_PROFILE, response);
        navigation.reset({index: 0, routes: [{name: Routers.MAIN_PAGE}]});

      }
    })
    .catch(error => {
      setLoading(false);
      console.log("error")
      console.log(error)
      const err = error.toJSON().message;
    });
  }

  return (
    <View>

      <TextInput
        onChange={value => {
          setEmail(value);
        }}
        // icon={} 
        // value={} 
        placeholder={'Nomor Hp'}
        //  onPres
        title={'Nomor Hp'}
        error={emailError}
        editable={!loading}
      />

      <TextInput
         onChange={value => {
          setPassword(value);
        }}
        icon={activeEye ? 'ic_eye_close' : 'ic_eye_open'} 
        // value={} 
        placeholder={'Password'}
         onPress = {() => setActiveEye(!activeEye)}
        title={'Password'}
        secureTextEntry={activeEye}
        error={passwordError}
        editable={!loading}
      />

      <TouchableOpacity
        onPress={() => navigation.navigate(Routers.FORGOTE_PASSWORD_SCREEN, {forgote: true})}>
        <Text
          style={{
            fontSize: Scale(12),
            color: (Colors.black),
            fontWeight: '300',
            marginHorizontal: Scale(18),
            marginVertical: Scale(8),
            alignSelf: 'flex-end'
          }}>
          {'Lupa Password?'}
        </Text>
      </TouchableOpacity>
      

      <Buttons
        loading={loading}
        disabled ={loading}
        style ={{marginTop : Scale(40), backgroundColor: loading ? Colors.greenWhite : Colors.primaryColor}}
        onPress={() => onPressLogin()}
        title={'Masuk'} />


      <View style={{ flexDirection: 'row', alignSelf: 'center', marginVertical: Scale(20) }}>

      <View style={{flex:1, height: Scale(1), backgroundColor: Colors.line}}/>

        <View>
        <Text
          style={{
            fontSize: Scale(12),
            color: (Colors.black),
            fontWeight: '600',
            marginTop: Scale(-10),
            marginHorizontal: Scale(28),
            textAlign:'center'
          }}>
          {'Atau masuk lewat'}
        </Text>

        <View style={{ flexDirection: 'row', marginVertical: Scale(30), justifyContent:'center' }}>

        <Image
          style={{ height: Scale(20), width: Scale(240) }}
          source={getIcon('ic_google')}
          resizeMode='contain' />

      </View>
        </View>

        <View style={{flex:1, height: Scale(1), backgroundColor: Colors.line}}/>
      </View>

      
      
      
    </View>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
export default Login;