// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  Image,
  ScrollView,
  SafeAreaView,
  FlatList
} from 'react-native';
import { Colors } from '../../../../Assets/Colors';
import { getIcon } from '../../../../Assets/Icon';
import Toolbar from '../../../../Component/Toolbar';
import { Metrics, Scale } from '../../../../utils/size';
import TextInput from '../../../../Component/TextInput';
import Buttons from '../../../../Component/Button';
import { getData, removeData } from '../../../../utils/Storage';
import { Constants } from '../../../../utils/Constans';
import ItemOrder from '../ItemOrder';
import ModalConfirmationOrder from '../../../../Component/ModalConfirmationOrder';
import { Routers } from '../../../../utils/Routers';
import TabLayout from '../TabLayout';
import ModalStatusCart from '../../../../Component/ModalStatusCart';
import ModalStatusReadyToSend from '../../../../Component/ModalStatusReadyToSend';
import ModalConformationSendHub from '../../../../Component/ModalConformationSendHub';
import ItemOrderCoHub from '../ItemOrderCoHub';
import { getURLHub, postURL } from '../../../../utils/services/API';
import { JSONAxioGet, JSONAxioPost } from '../../../../utils/services/JsonService';
import Loading from '../../../../Component/loading';
import PopUp from '../../../../Component/popUp';

const TakeOrder = ({route, navigation }) => {
  const [showModalConfirm, setShowModalConfirm] = useState(false);
  const [selectItem, setSelectItem] = useState(null);
  let [search,setSearch] = useState("");
  let [titleType,setTitleType] = useState("Semua Produk");
  let [loading, setLoading] = useState(false);
  let [loadingFull, setLoadingFull] = useState(false)
  let [showStatus, setShowStatus] = useState(false);
  let[totalPage, setTotalPage] = useState(1);
  let[currentPage, setCurrentPage] = useState(1);
  
  let [title,setTitle] = useState("Semua Produk");
  let [profesi, setProfesi] = useState([
    { name: "Personal", status: true },
    { name: "Hub", status: false }]
    );
    const [showType, setShowType] = useState(false);
    const [tabTypeFlag, setTabTypeFlag] = useState('allProduct');
    const [tabFlag, setTabFlag] = useState('0');
    let [switchAccount, setswitchAccount] = useState(false);
    let [eyePass, setEyePass] = useState(false);
    let [newsOrder, setNewOrder] = useState([]);
    let [isHub, setIsHub] = useState(null);

    const [dataDetil, setDataDetil] = useState(null);
  let [warning, setWarning] = useState(false);
  let [contentWarning, setContentWarning] = useState(null);
 
  useEffect(() => {
    getData(Constants.SESSION_HUB).then(res => {
      setswitchAccount(res ? true :  false);
      setIsHub(JSON.parse(res).userRole);
      getdataHubCohub(search, route.params?.filter?.id, JSON.parse(res).userRole, currentPage);
      setTitle(JSON.parse(res).userRole === "COHUB" ? route.params?.filter?.name : "Semua Produk");
      setTabFlag(route.params?.filter?.id ? route.params?.filter?.id : "0")
    });
  }, [route.params]);

  useEffect(() => { 
    
  }, []);

  const selectedItem = (item) => {

    var param = {
      "no_dst": item.no_dst
    }

    setLoading(true);

    getData(Constants.SESSION_USER_PROFILE).then(res => {
      JSONAxioPost(postURL((isHub === "HUB" ? 'api_hub_terima_dst' : route.params?.urlTakeOreder), null), param, res.result.token)
        .then(respone => {
          const response = respone?.data;
          setLoading(false);
          if (response?.statusCode == 1) {
            navigation.navigate(Routers.SUCCESS_SCREEN, { title: 'Berhasil Diterima', desc: 'Dokumen Serah Terima Berhasil Anda Terima Silakan Lanjutkan Proses Pengiriman', titleButton: 'Pesanan Siap Kirim' });
          } else {
            cekError(response.statusCode, response.message);
          }
        })
        .catch(error => {
          setLoading(false);
          cekError(2, null);

        });

    });
  }

  const goBack =(item)=>{
    navigation.goBack()
  }

  const onPresHubSendConfirm = (item) => {
    navigation.navigate(Routers.SUCCESS_SCREEN, { title: 'Pengiriman Diproses', desc: 'Terimakasih , Pengiriman produk kamu telah berhasil dan sedang di proses , Klik tombol dibawah untuk cek status pengiriman kamu', titleButton: 'Ambil Kiriman Baru' })
    setShowModalConfirm(!showModalConfirm)
  }

  const selectSetTabFlag = async item => {
    setTabFlag(item.id);
    setTitle(item.name);
    setShowStatus(false);
    refresh("", item.id, isHub, 0)
    // getdataHubCohub(search, item.id, isHub, currentPage);
  }

  const refresh = (search, status, Hub,) => {
    setNewOrder([]);
    setCurrentPage(0);
    getdataHubCohub("", status, Hub, 0)
  }

  const handleLoadMore = () => {
   
    if (currentPage < totalPage) {
      console.log("Load More ", currentPage, " totalPage ", totalPage )
       getdataHubCohub(search, tabFlag, isHub,(currentPage+1))
    }
  };
  
  const getdataHubCohub = (search, status, Hub, currentPage) => {

    getData(Constants.SESSION_USER_PROFILE).then(res => {


      var paramsListProduct = route.params?.search ? {
        search: search,
        pagination: currentPage,
        status: status,
        hubLocation: ''
      } : {
        search: search ? search : "",
        pagination: currentPage,
        noSetoranHub: route.params?.parameter?.noDst
      }

      console.log(route.params?.parameter)
      getListProductHubCoHub(paramsListProduct, res.result.token, Hub, currentPage);
    })
  }

  const getListProductHubCoHub = (params, token, Hub, currentPage) => {
    setLoading(true)
    JSONAxioGet(getURLHub(route.params?.search ? (Hub === "HUB" ? 'api-hub-list-dst': (route.params?.url? route.params?.url: 'api-cohub-list-dst')) : "api_cohub_detail_dst", params), null, token)
      .then(respone => {
        setLoading(false);
        const response = respone.data;
        if (response.statusCode == 1) {
          setNewOrder([...newsOrder, ...response.result]);
          // setNewOrder(response.result);
          setTotalPage(response.totalPage)
          setCurrentPage(currentPage)
        } else {
          setNewOrder([]);
          cekError(response.statusCode, response.message);

        }
      })
      .catch(error => {
        setLoading(false);
        console.log("error")
        console.log(error)
      });
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
        setContentWarning({
          title: "Oooops !!",
          desc: errorMessage,
          titleButton: "Login Kembali",
          statusCode: statusCode
        })
    } 
    else if (statusCode == 1){
      setContentWarning({
        title: "Yeey !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else {
      setLoading(false);
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }

  const actionButton = () => {
    setWarning(false);
    setContentWarning(null)
    if (contentWarning?.statusCode == 401 || contentWarning?.statusCode == 400) {
      removeData(Constants.SESSION_USER_PROFILE).then(() => {
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: "LoginStack"}] });
        });
      });
    }
    
  }

  const onPresDetil =(item) => {
    if(search) {
      navigation.navigate(Routers.DETIL_DOKUMEN_SERAH_TERIMA_SCREEN, {title: route.params?.title, data: item, titleButtonDetil: route.params?.buttonName, qrCode: route.params?.qrCode, showPhone: route.params?.showPhone, showOtherButton: route.params?.showOtherButton, urlTakeOreder : route.params?.urlTakeOreder})
    } else {
      var params = {
        no_dpp : item.noDpp
      }

      getData(Constants.SESSION_USER_PROFILE).then(res => {
        JSONAxioGet(getURLHub('api_cohub_detail_dpp', params), null, res.result.token)
          .then(respone => {
            setLoading(false);
            const response = respone.data;

            if (response.statusCode == 1) {

              var isArray = Array.isArray(response.result);
              var results = null;
              if (isArray) {
                results = response.result[0];
              } else {
                results = response.result;
              }
              console.log(results)
              navigation.navigate(Routers.DETIL_PENGIRIMAN_SCREEN, { data: results })


            } else {

              cekError(response.statusCode, response.message);

            }
          })
          .catch(error => {
            setLoading(false);
            console.log("error")
            cekError(4, null);
          });
      })
    }
   
  }

  return (
    <SafeAreaView style={{ flex: 1, }}>
      <View style={{ flex: 1, backgroundColor: Colors.white }}>


        <View style = {{borderBottomColor :Colors.greenWhite, borderBottomWidth: Scale(10)}}>
          {<View style={{ backgroundColor: Colors.white, flexDirection: 'row', paddingBottom: Scale(0), alignItems: 'center', justifyContent: 'center' }}>

            <View style={{ flex: 0.1, justifyContent: 'center', paddingLeft: Scale(8), marginTop: Scale(16) }}>
              <TouchableOpacity
                onPress={goBack}>
                <Image
                  style={[{ height: Scale(30), width: Scale(30), tintColor: Colors.primaryColorHub }]}
                  source={getIcon('ic_arrow_left_line')}
                  resizeMode='contain' />
              </TouchableOpacity>

            </View>

            <View style={{ flex: 1 }}>
              {route.params?.search && <TextInput
                style={{ marginTop: Scale(20) }}
                onChange={value => setSearch(value)}
                icon={'ic_search'}
                value={search}
                placeholder={'Cari Pesanan'}
                onPress={() => { getdataHubCohub(search, tabFlag, isHub)}}
                title={''}
                error={null}
              />}

              {!route.params?.search && <Text style={{ fontSize: Scale(16), color: Colors.primaryColorHub, textAlign: 'center', marginBottom: Scale(18), marginTop: Scale(16), paddingTop: Scale(16) }}>{route.params?.title}</Text>}
            </View>

            {isHub === "HUB" && <View style={{ flex: 0.1, alignItems: 'center', paddingTop: Scale(20), paddingRight: Scale(16) }}>
            {/* navigation.navigate(Routers.CAMERA_SCAN_QR_SCREEN, {page: Routers.DETIL_DOKUMEN_SERAH_TERIMA_SCREEN}) */}
              <TouchableOpacity
                onPress={() => console.log("")}>
                <Image
                  style={{ height: Scale(30), width: Scale(30), marginHorizontal: Scale(8), tintColor: switchAccount ? Colors.primaryColorHub : Colors.primaryColor }}
                  source={getIcon('ic_scan')}
                  resizeMode='contain' />
              </TouchableOpacity>

            </View>}
          </View>}

          {route.params?.search && <TabLayout
            show={'readyToSend' != tabFlag ? true : false}
            title={title}
            titleType={titleType}
            openStatus={() => setShowStatus(true)}
            openType={() => setShowType(true)}
          />}
        </View>
        

        <FlatList
              style={{ flex: 1, backgroundColor: Colors.greenWhite }}
              refreshing={loading}
              onRefresh={() => {route.params?.search ? refresh(search, tabFlag, isHub) : console.log("")}}
              data={newsOrder.length == 0 ? [''] : newsOrder}
              onEndReachedThreshold={0.4}
              onEndReached={handleLoadMore.bind(this)}
              renderItem={({ item, i }) =>
              (
                <View>
                 {(newsOrder.length != 0) && <ItemOrderCoHub
                    search={route.params?.search}
                    navigation={navigation}
                    key={i}
                    onPressSend={() => selectedItem(item)}
                    onPress={() => onPresDetil(item)}
                    data={item}
                    titleButton={route.params?.buttonName} />}

                  {(newsOrder.length == 0) && <View style={{ height: Metrics.screenHeight / 1.5, justifyContent: 'center', alignItems: 'center', paddingHorizontal: Scale(16) }}>

                    <Image
                      style={{ height: Scale(150), width: Scale(150) }}
                      source={getIcon('img_oops')}
                      resizeMode='contain' />

                    <Text style={{ fontSize: Scale(18), textAlign: 'center' }}>Anda belum Mendapatkan Pesanan Baru saat ini</Text>
                  </View>}
                </View>
                )
              }
            />


        <ModalStatusReadyToSend
        isHubSend={route.params?.isHubSend}
        isHubGet={route.params?.isHubGet}
         isDataCohubPabrik ={route.params?.isDataCohubPabrik}
         isDataPengambilanHub={route.params?.isDataPengambilanHub}
          // isDataCohub = {isHub === "HUB" ? false : true}
          readySend = {false}
          onPresStatus={(item) => selectSetTabFlag(item)}
          onClose={() => setShowStatus(false)}
          ShowStatus={showStatus} />

        <ModalConformationSendHub
          data={dataDetil}
          onPresButtonConfirm={() => onPresHubSendConfirm()}
          onCloses={() => setShowModalConfirm(false)}
          ShowComment={showModalConfirm}
        />

        {/* <Loading
          visible={loading} /> */}

        <PopUp
          visible={warning}
          onPressButton={() => { actionButton() }}
          title={contentWarning?.title}
          desc={contentWarning?.desc}
          titleButton={contentWarning?.titleButton} />
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
  imgRow: { height: Scale(90), width: Scale(90) },
  text400: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
});
export default TakeOrder;