// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  Image,
  ScrollView,
  SafeAreaView,
  RefreshControl
} from 'react-native';
import { Colors } from '../../Assets/Colors';
import { getIcon } from '../../Assets/Icon';
import Toolbar from '../../Component/Toolbar';
import { Scale } from '../../utils/size';
import
FontAwesome
  from 'react-native-vector-icons/FontAwesome5';
import Buttons from '../../Component/Button';
import { Routers } from '../../utils/Routers';
import { JSONAxioGet,JSONAxioDelete } from '../../utils/services/JsonService';
import { getURL,postURL, deleteURL } from '../../utils/services/API';
import { Constants } from '../../utils/Constans';
import { getData } from '../../utils/Storage';

const PaymentMethodeScreen = ({ navigation }) => {

  let [dataCod, setDataCod] = useState([]);
   
  let [dataEwalet, setDataEwalet] = useState([
    // { name: 'Gopay', icon: 'ic_gopay', category: 'E-Walet', height: Scale(25), width: Scale(60) },
    // { name: 'Dana', icon: 'ic_dana', category: 'E-Walet', height: Scale(20), width: Scale(50) },
    // { name: 'Ovo', icon: 'ic_ovo', category: 'E-Walet',height: Scale(15), width: Scale(30) }
  ]);

  let [dataTransfer, setDataTransfer] = useState([
    // { name: 'BCA', icon: 'ic_bca', category: 'Virtual Account Bank', height: Scale(20), width: Scale(50) },
    // { name: 'Mandiri', icon: 'ic_mandiri', category: 'Virtual Account Bank', height: Scale(20), width: Scale(50) },
    // { name: 'Cimb Niaga', icon: 'ic_cimg', category: 'Virtual Account Bank', height: Scale(20), width: Scale(60) }
  ]);
  let [dataVa, setDataVa] = useState([
    // { name: 'Gopay', icon: 'ic_gopay', category: 'E-Walet', height: Scale(25), width: Scale(60) },
    // { name: 'Dana', icon: 'ic_dana', category: 'E-Walet', height: Scale(20), width: Scale(50) },
    // { name: 'Ovo', icon: 'ic_ovo', category: 'E-Walet',height: Scale(15), width: Scale(30) }
  ]);
  let [token, setToken] = useState(0)
  let [loading, setLoading] = useState(false)

  useEffect(() => {
    getdata()

  }, [token]);

  const selectSendBy =(item)=>{
    navigation.navigate(Routers.CONFIRMATION_ORDER_PAGE, {paymentMethode : item})
  }

  const goBack =(item)=>{
    navigation.goBack()
  }

  const getdata = () => {
    getData(Constants.SESSION_USER_PROFILE).then(res => {
      
      setToken(res.result.token)
      getListTypeDelivery();
     })
  }

  const getListTypeDelivery = (params) => {
    setLoading(true)
    // setDataProv([])
    JSONAxioGet(getURL('api-list-type-payment', null), null, token)
    .then(respone => {
      setLoading(false);
      
      const response = respone.data;
      if (response.statusCode == 1) {
        console.log(JSON.stringify(response))

        var dataEwaletArr = [];
        response?.result?.group_ewallet.map((item, i) => {
          if (item.payment_code === "dana"){
            dataEwaletArr.push({payment_code: item.payment_code, name: 'Dana', icon: 'ic_dana', category: 'E-Walet', height: Scale(20), width: Scale(50)})
          }

          if (item.payment_code === "gopay"){
            dataEwaletArr.push({payment_code: item.payment_code, name: 'Gopay', icon: 'ic_gopay', category: 'E-Walet', height: Scale(25), width: Scale(60) })
          }
          
          if (item.payment_code === "ovo"){
            dataEwaletArr.push({payment_code: item.payment_code, name: 'Ovo', icon: 'ic_ovo', category: 'E-Walet',height: Scale(15), width: Scale(30)})
          }
          if (item.payment_code === "qris"){
            dataEwaletArr.push({payment_code: item.payment_code, name: 'Qris', icon: 'ic_qris', category: 'E-Walet',height: Scale(15), width: Scale(30)})
          }
          if (item.payment_code === "shopee"){
            dataEwaletArr.push({payment_code: item.payment_code, name: 'Shopee', icon: 'ic_shopee', category: 'E-Walet',height: Scale(25), width: Scale(80)})
          }
        })
        setDataEwalet(dataEwaletArr)

        var dataTransferArr = [];
        response?.result?.group_bank.map((item, i) => {
          if (item.payment_code === "tbca"){
            dataTransferArr.push({payment_code: item.payment_code, name: 'BCA', icon: 'ic_bca', category: 'Virtual Account Bank', height: Scale(20), width: Scale(50)})
          }

          if (item.payment_code === "tcimbniaga"){
            dataTransferArr.push({payment_code: item.payment_code, name: 'Cimb Niaga', icon: 'ic_cimg', category: 'Virtual Account Bank', height: Scale(20), width: Scale(60) })
          }
          
          if (item.payment_code === "tmandiri"){
            dataTransferArr.push({payment_code: item.payment_code, name: 'Mandiri', icon: 'ic_mandiri', category: 'Virtual Account Bank', height: Scale(20), width: Scale(50)})
          }
        })
        setDataTransfer(dataTransferArr)
        
        setDataCod([{payment_code: response.result.group_cod[0].payment_code, name : 'Cash On Delivery (COD)', category: null, icon: 'ic_cod', height: Scale(20), width: Scale(40)}])
        // setDataProv(response.result)
      } else {
       
      }
    })
    .catch(error => {
      setLoading(false);
      console.log("error")
      console.log(error)
    });
  }

  return (
    <SafeAreaView style={{ flex: 1, }}
     refreshControl={
            <RefreshControl refreshing={loading} onRefresh={getListTypeDelivery} />
          }>
      <View style={{ flex: 1, backgroundColor: Colors.white }}>

        <Toolbar
          onPress={goBack}
          title={'Metode Pembayaran'} /> 

          <ScrollView>
            <View style={{flex:1}}>
              {
                dataCod.map((item, i) => (
                  <View style={{ marginHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2), }}>
                    <TouchableOpacity
                      onPress={() => selectSendBy(item)}>
                      <View style={{}}>
                        <View style={{ flexDirection: 'row' }}>
                          <View style={{ flex: 1 }}>
                            <Text style={{ color: Colors.black, fontWeight: '400' }}>{item.name}</Text>
                          </View>
                          {item.icon && <View style={{ flex: 0.2, alignItems: 'flex-end' }}>
                            <Image
                              style={{ height: item.height, width: item.width, marginHorizontal: Scale(8) }}
                              source={getIcon(item.icon)}
                              resizeMode='contain' />
                          </View>}
                        </View>
                      </View>
                    </TouchableOpacity>
                  </View>
                ))
            }
            {dataEwalet.length >0 && <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
              <Text style={{ color: Colors.black, fontWeight: '600', fontSize: Scale(14) }}>{"E-Walet"}</Text>
            </View>}

            {
                dataEwalet.map((item, i) => (
                  <View style={{ marginHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2)}}>
                    <TouchableOpacity
                      onPress={() => selectSendBy(item)}>
                      <View style={{}}>
                        <View style={{ flexDirection: 'row' }}>
                          <View style={{ flex: 1 }}>
                            <Text style={{ color: Colors.black, fontWeight: '400' }}>{item.name}</Text>
                          </View>
                          <View style={{ flex: 0.2, alignItems: 'flex-end' }}>
                            <Image
                              style={{ height: item.height, width: item.width, marginHorizontal: Scale(8) }}
                              source={getIcon(item.icon)} 
                              resizeMode='contain'/>
                          </View>
                        </View>
                      </View>
                    </TouchableOpacity>
                  </View>
                ))
            }

            {dataTransfer.length>0 && <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
              <Text style={{ color: Colors.black, fontWeight: '600', fontSize: Scale(14) }}>{"Transfer Bank"}</Text>
            </View>}

            {
                dataTransfer.map((item, i) => (
                  <View style={{ marginHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2)}}>
                    <TouchableOpacity
                      onPress={() => selectSendBy(item)}>
                      <View style={{}}>
                        <View style={{ flexDirection: 'row' }}>
                          <View style={{ flex: 1 }}>
                            <Text style={{ color: Colors.black, fontWeight: '400' }}>{item.name}</Text>
                          </View>
                          <View style={{ flex: 0.2, alignItems: 'flex-end' }}>
                            <Image
                              style={{ height: item.height, width: item.width, marginHorizontal: Scale(8) }}
                              source={getIcon(item.icon)} 
                              resizeMode='contain'/>
                          </View>
                        </View>
                      </View>
                    </TouchableOpacity>
                  </View>
                ))
            }

            {dataVa.length > 0 && <View style={{ paddingHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
              <Text style={{ color: Colors.black, fontWeight: '600', fontSize: Scale(14) }}>{"Virtual Account"}</Text>
            </View>}

            {
              dataVa.map((item, i) => (
                <View style={{ marginHorizontal: Scale(16), paddingVertical: Scale(16), borderColor: Colors.gray, borderBottomWidth: Scale(2) }}>
                  <TouchableOpacity
                    onPress={() => selectSendBy(item)}>
                    <View style={{}}>
                      <View style={{ flexDirection: 'row' }}>
                        <View style={{ flex: 1 }}>
                          <Text style={{ color: Colors.black, fontWeight: '400' }}>{item.name}</Text>
                        </View>
                        <View style={{ flex: 0.2, alignItems: 'flex-end' }}>
                          <Image
                            style={{ height: item.height, width: item.width, marginHorizontal: Scale(8) }}
                            source={getIcon(item.icon)}
                            resizeMode='contain' />
                        </View>
                      </View>
                    </View>
                  </TouchableOpacity>
                </View>
              ))
            }
            </View>
          </ScrollView>

          

          

        </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
export default PaymentMethodeScreen;