// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, {useEffect, useState }  from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  ScrollView,
  View,
  Text,
  SafeAreaView
} from 'react-native';
import { Colors } from '../../Assets/Colors';
import { getIcon } from '../../Assets/Icon';
import TextInput from '../../Component/TextInput';
import { Scale } from '../../utils/size';
import Login from './Login';
import Register from './Register';
import TabLogin from './Tab';
import Profile from './Profile';
import { getData } from '../../utils/Storage';
import { Constants } from '../../utils/Constans';
import { Eng } from '../../utils/String';

const HomeScreen = ({ route, navigation }) => {
  let [activeLogin, setActiveLogin] = useState(true);
  let [activeRegister, setActiveRegister] = useState(false);
  let [login, setLogin] = useState(false);
  useEffect(() => {
    getData(Constants.SESSION_USER_PROFILE).then(res => {
      setLogin(res ? true :  false);
    })

    
    
  }, [route.params]);

  const onPressTab =()=>{
    setActiveLogin(!activeLogin);
    setActiveRegister(!activeRegister);
  }

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: Colors.greenWhite}}>

      {/* <Profile navigation={navigation}/> */}
      
      
      { login ?
        <Profile navigation={navigation}/>
        :
        <View style={{ flex: 1, padding: 16, backgroundColor: Colors.greenWhite }}>

          <TabLogin
            activeLogins={activeLogin}
            onPressTab={(loginActive) => setActiveLogin(loginActive)}
          />
          <ScrollView style={{ flex: 1 }}>
            {activeLogin && <Login navigation ={navigation} />}
            {!activeLogin && <Register
            route={route}
              gotoLogin={(loginActive) => setActiveLogin(loginActive)}
              navigation={navigation} />}
          </ScrollView>

          <Text style={{textAlign:'center', fontSize: Scale(10)}}>{Eng.VERSION_NAME}</Text>

        </View>}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
});
export default HomeScreen;