// React Native Bottom Navigation
// https://aboutreact.com/react-native-bottom-navigation/
import React, { useEffect, useState } from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  Text,
  Image,
  ScrollView,
  SafeAreaView,
  FlatList
} from 'react-native';
import { Colors } from '../../../Assets/Colors';
import { getIcon } from '../../../Assets/Icon';
import { Metrics, Scale } from '../../../utils/size';
import TextInput from '../../../Component/TextInput';
import { getData, removeData } from '../../../utils/Storage';
import { Constants } from '../../../utils/Constans';
import ItemOrder from './ItemOrder';
import { Routers } from '../../../utils/Routers';
import ModalStatusReadyToSend from '../../../Component/ModalStatusReadyToSend';
import ModalConformationSendHub from '../../../Component/ModalConformationSendHub';
import { JSONAxioGet, JSONAxioGetNew, JSONAxioPost } from '../../../utils/services/JsonService';
import { getURLHub, getURL, postURL } from '../../../utils/services/API';
import PopUp from '../../../Component/popUp';
import Loading from '../../../Component/loading';
import TabLayout from '../../HomeScreen/HubScreen/TabLayout';
import Buttons from '../../../Component/Button';
import ModalSetoranCodHub from '../../../Component/ModalSetoranCodCoHub';
import { currency } from '../../../utils/General';
import ModalSetoranCodFoloni from '../../../Component/ModalSetoranCodFoloni';
import ModalListPayment from '../../../Component/ModalListPayment';

const CodCoHub = ({ route, navigation }) => {
  const [showModalConfirm, setShowModalConfirm] = useState(false);
  const [selectItem, setSelectItem] = useState(null);
  let [search, setSearch] = useState(null);
  let [titleType, setTitleType] = useState("Setoran Hub");
  
  let [loading, setLoading] = useState(false);
  let [loadingFull, setLoadingFull] = useState(false);
  let [showStatus, setShowStatus] = useState(false);
  let [title, setTitle] = useState("Setoran Hub");
  const [tabFlag, setTabFlag] = useState('1');
  let [switchAccount, setswitchAccount] = useState(false);
  let [warning, setWarning] = useState(false);
  let [contentWarning, setContentWarning] = useState(null);
  let [token, setToken] = useState(null);
  let [items, setItem] = useState(null);
  let [arraySelection, setArraySelection] = useState([]);
  let [originalArraySelection, setOriginalArraySelection] = useState([]);
  let [isUseSaldo, setIsUseSaldo] = useState(false);
  let [idSetoranCoHub, seIdSetoranCoHub] = useState(0);
  let [pressDetil, setPressDetil] = useState(true);

  let [groupArraySelection, setGroupArraySelection] = useState([]);
  let [totalPrice, setTotalPrice] = useState(0);
  let [showModalStatus, setShowModalStatus] = useState(false);
  let [showModalSetoranFoloni, setShowModalSetoranFoloni] = useState(false);
  let [showModalListPayment, setShowModalListPayment] = useState(false);
  let [paymentMethode, setPaymentMethode] = useState(
    { name: "Pilih Metode Pembayaran Untuk Setoran", icon: null, category: null, height: Scale(20), width: Scale(50) });

  useEffect(() => {
    getData(Constants.SESSION_HUB).then(res => {
      setswitchAccount(res ? true : false);
    });
  }, [route.params]);
  let [newsOrder, setNewOrder] = useState([]);
  const [dataDetil, setDataDetil] = useState(null);

  useEffect(() => {
    getdataHubCohub("", tabFlag);

  }, []);

  useEffect(() => {

    if (!pressDetil){
      setShowModalSetoranFoloni(true)
    }
   
   
  }, [paymentMethode, isUseSaldo, totalPrice, showModalSetoranFoloni]);

  const selectedItem = (item) => {

    getDetilProductHubCoHub(item, token, "modal", item)
  }

  const onPresHDetil = (item) => {
    setItem(item)

    getDetilProductHubCoHub(item, token, "page", item)
  }

  const goBack = (item) => {
    navigation.goBack()
  }

  const onPresHubSendConfirm = (value) => {
    setShowModalConfirm(!showModalConfirm)
    if (value) {
      navigation.navigate(Routers.SUCCESS_SCREEN, { title: 'Pengiriman Diproses', desc: 'Terimakasih , Pengiriman produk kamu telah berhasil dan sedang di proses , Klik tombol dibawah untuk cek status pengiriman kamu', titleButton: 'Kirim Pesanan Lainnya' })
    }
  }

  const selectSetTabFlag = async item => {
    setTabFlag(item.id);
    setTitle(item.name);
    setShowStatus(false);
    getdataHubCohub(search, item.id);
  }

  const getdataHubCohub = (search, status) => {

    getData(Constants.SESSION_USER_PROFILE).then(res => {

      if (res) {
        setToken(res.result.token);
      }

      var paramsListProduct = {
        search: search ? search : "",
        pagination: '',
        filter:1
      }

      getListProductHubCoHub(paramsListProduct, res.result.token, status);
    })
  }

  const getUrl = (status) => {
    setArraySelection([]);
    setGroupArraySelection([])
    console.log("Status >> ", status)
      if (status == 1){
        return 'api_cohub_setoran_hub'
      } else if (status == 2){
        return 'api_cohub_siap_setor'
      } else if (status == 3){
        return 'api_cohub_belum_konfirmasi'
      }  else if (status == 4){
        return 'api_cohub_belum_konfirmasi_admin'
      } else if (status == 5){
        return 'api_cohub_setoran_tolak'
      } else if (status == 6){
        return 'api_cohub_setoran_selesai'
      }
      else if (status == 7){
        return 'api_cohub_belum_konfirmasi'
      }
  }

  const getListProductHubCoHub = (params, token, status) => {
    setNewOrder([]);
    setLoading(true);
    JSONAxioGet(getURLHub(getUrl(status), params), null, token)
      .then(respone => {
        setLoading(false);
        const response = respone.data;
        if (response.statusCode == 1) {
          console.log(response)
          setNewOrder(response.result?.transaksi ? response.result.transaksi : []);
        } else {

          cekError(response.statusCode, response.message);

        }
      })
      .catch(error => {
        setLoading(false);
        console.log("error")
        console.log(error)
      });
  }


  const getDetilCoHub = (params) => {
    setLoading(true);
    console.log(params)
    JSONAxioGet(getURL("api_cohub_detail_setoran_cohub", params), null, token)
      .then(respone => {
        setLoading(false);
        const response = respone.data;
        if (response.statusCode == 1) {
          setPressDetil(false)
          setDataDetil( response?.result)
          const groupedTech = Object.entries(
            // What you have done
            response?.result.listSetoran.reduce((acc, { idSetoranHub, namaHub, nilaiCod }) => {
              // Group initialization
              if (!acc[namaHub]) {
                acc[namaHub] = [];
              }
              
              // Grouping
              // FIX: only pushing the object that contains id and value
              acc[namaHub].push({ idSetoranHub, nilaiCod });
          
              return acc;
            }, {})
          ).map(([namaHub, list]) => ({ namaHub, list }));
          
          setGroupArraySelection(groupedTech) 
          setPaymentMethode( response?.result.metodeBayar)
          
          setIsUseSaldo(response?.result.flagSaldo)
          totalAllPriceSelection(response?.result.listSetoran)
          
          setPressDetil(true)
          // setNewOrder(response.result?.transaksi ? response.result.transaksi : []);
        } else {

          cekError(response.statusCode, response.message);

        }
      })
      .catch(error => {
        setLoading(false);
        console.log("error")
        console.log(error)
      });
  }

  const cekError = (statusCode, errorMessage) => {
    setWarning(true);
    if (statusCode == 401 || statusCode == 400) {
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "Login Kembali",
        statusCode: statusCode
      })
    }
    else if (statusCode == 1) {
      setContentWarning({
        title: "Yeey !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
    else {
      setLoading(false);
      setContentWarning({
        title: "Oooops !!",
        desc: errorMessage,
        titleButton: "OK",
        statusCode: statusCode
      })
    }
  }

  const actionButton = () => {
    setWarning(false);
    setContentWarning(null)
    if (contentWarning?.statusCode == 401 || contentWarning?.statusCode == 400) {
      removeData(Constants.SESSION_USER_PROFILE).then(() => {
        removeData(Constants.SESSION_HUB).then(() => {
          navigation.reset({ index: 0, routes: [{ name: "LoginStack" }] });
        });
      });
    }

  }

  const onpressSelection = (item) => {
    var arraySelect = arraySelection;
    var groupArraySelect = groupArraySelection;
    var result = arraySelect.filter(object => object?.idSetoranHub === item?.idSetoranHub);

    var resultGroup = groupArraySelect.filter(object => object?.namaHub.toUpperCase() === item?.namaHub.toUpperCase());
    if(resultGroup.length == 0){
      var group = {
        namaHub : item?.namaHub,
        total : item?.nilai,
        list : [item]
      }
      setGroupArraySelection([...groupArraySelection, group])
    } else {
      var index = groupArraySelect.findIndex(object => object?.namaHub.toUpperCase() === item?.namaHub.toUpperCase());
      var resultGroupList = groupArraySelect[index].list.filter(object => object?.idSetoranHub === item?.idSetoranHub);
      
      if(resultGroupList.length == 0){
        groupArraySelect[index].list.push(item)

        setGroupArraySelection(totalGroupPriceSelection(groupArraySelect))
      } else {
        var index = groupArraySelect.findIndex(object => object?.namaHub.toUpperCase() === item?.namaHub.toUpperCase());
        var resultGroupList = groupArraySelect[index].list.filter(object => object?.idSetoranHub != item?.idSetoranHub);
        groupArraySelect[index].list = resultGroupList

        if (groupArraySelect[index].list.length == 0){
          var resultGroup = groupArraySelect.filter(object => object?.namaHub.toUpperCase() != item?.namaHub.toUpperCase());
          setGroupArraySelection(totalGroupPriceSelection(resultGroup))
        } else {
          setGroupArraySelection(totalGroupPriceSelection(groupArraySelect))
        }
        
      }
      
    }
   
    if(result.length == 0){
      var resultArraySelection = arraySelection
      

      setArraySelection([...arraySelection, item])
      resultArraySelection.push(item)
      totalAllPriceSelection(resultArraySelection)
    } else {
      var result = arraySelect.filter(object => object?.idSetoranHub !== item?.idSetoranHub);
      setArraySelection(result)
      totalAllPriceSelection(result)
    }

    
   
  }

  const totalGroupPriceSelection = (array) => {
    array.map((item, i) => {
      var totals = 0
      item.list.map((items, i) => {

        console.log(items.nilai)
        totals = totals + items.nilai
      })
      item.total = totals
    })

    return array;
  }

  const totalAllPriceSelection = (array) => {
    var totals = 0
    array.map((item, i) => {
      if (item?.nilai)  {
        totals = (tabFlag == 2) ? totals + item.nilai : totals + item.nilai
      } else {
        var nilaiCod = parseInt(item.nilaiCod.replace('Rp.','').replace('.',''))
        totals = (tabFlag == 2) ? totals + nilaiCod : totals + nilaiCod
      }
      
    })
    setTotalPrice(totals)
  }

  const checkSelection = (item) => {
    var result = arraySelection.filter(object => object?.idSetoranHub == item?.idSetoranHub); 
    return (result.length == 0 ? false : true)
  }


  const getDetilProductHubCoHub = (params, token, page, item) => {
    
    if (tabFlag == 1){
      navigation.navigate((Routers.COD_SCREEN), { title: "Setoran COD",  parameter : params ,filter: { name: 'Semua Status', flag: 'all', status: true, id: 0 }, buttonName: 'Terkirim', qrCode: false, showPhone: true, showOtherButton: false, isDataCohubPabrik: false, isDataPengambilanHub: false, isHubSend: false, isHubGet: false, search: false })
    } else if (tabFlag == 2){
      cekError(2, "Di Figma Belum Ada Nomor API nya ...");
    } else if (tabFlag == 3){
      setPressDetil(true)
      getDetilCoHub(params)
    } else if (tabFlag == 4){
      setPressDetil(true)
      getDetilCoHub(params)
    } else if (tabFlag == 5){
      setPressDetil(true)
      getDetilCoHub(params)
    } else if (tabFlag == 6){
      setPressDetil(true)
      getDetilCoHub(params)
    }else if (tabFlag == 7){
      setPressDetil(true)
      getDetilCoHub(params)
    }

    
    // setLoadingFull(true);
    // JSONAxioGet(getURLHub('api_status_cair_saldo', params), null, token)
    //   .then(respone => {
    //     setLoadingFull(false);
    //     const response = respone.data;

    //     if (response.statusCode == 1) {

    //       var isArray = Array.isArray(response.result);
    //       results = response.result;
    //       // setDataDetil(results)

    //       if (page === 'modal') {
    //         setShowModalConfirm(!showModalConfirm)
    //       } else {
    //         console.log(JSON.stringify(results))
    //         setDetil(results)
    //         // setShowModalStatus(true)
    //         // navigation.navigate(Routers.DETIL_COMITION_SCREEN, { data: results, item: item })
    //       }


    //     } else {

    //       cekError(response.statusCode, response.message);

    //     }
    //   })
    //   .catch(error => {
    //     setLoadingFull(false);
    //     console.log("error")
    //     cekError(4, null);
    //   });
  }

  const postUrl = (draft) => {
      if (tabFlag == 1){
        return 'api_cohub_terima_setoran_cod'
      } else if (tabFlag == 2 && !draft){
        return 'api_cohub_kirim_bukti_setoran'
      } else if (tabFlag == 2 && draft){
        return 'api_cohub_proses_setoran_cod'
      } else if (tabFlag == 3){
        return null
      } else if (tabFlag == 4){
        return null
      } else if (tabFlag == 5){
        return null
      }
  }

  const titleButton = () => {
    if (tabFlag == 1){
      return 'Terima Setoran'
    } else if (tabFlag == 2){
      return 'Serahkan ke Foloni'
    } else if (tabFlag == 3){
      return null
    } else if (tabFlag == 4){
      return null
    } else if (tabFlag == 5){
      return null
    }
}

const onpressButton = () => {
  if (tabFlag == 1){
    setShowModalStatus(true);
  } else if (tabFlag == 2){
    setShowModalSetoranFoloni(true)
  } else if (tabFlag == 3){
    
  } else if (tabFlag == 4){
    console.log("")
  } else if (tabFlag == 5){
    console.log("")
  }
}


  const parameterPost = (paymentCode) => {

   
    setOriginalArraySelection(tabFlag> 2 ? dataDetil?.listSetoran  :arraySelection);

      if (tabFlag == 1){
        var parameter = arraySelection;

        parameter.map((item, i) => {
          delete item["namaHub"];
          delete item["totalDst"];
          delete item["nilaiCod"];
        })
    
       

        var parameters = {
          "listDst": parameter
        }

       

        return parameters;

      } else if (tabFlag == 2){
        var parameter = arraySelection;
        parameter.map((item, i) => {
          delete item["namaHub"];
          delete item["totalDst"];
          delete item["nilaiCod"];
        })
    
        var parameters = {
          "metodeBayar":paymentCode,
          "flagSaldo": isUseSaldo,
          "listSetoran": parameter
        }

        return parameters;


      } else if (tabFlag == 3){

        var parameters = {
          "idSetoranCohub": dataDetil?.idSetoranCohub
        }

        return parameters;
      } else if (tabFlag == 4){
        var parameters = {
          "listDst": parameter
        }

        return parameters;
      } else if (tabFlag == 5){
        var parameters = {
          "listDst": parameter
        }

        return parameters;
      }
  }


  const onpressSaveDraft=(paymentCode, draft)=>{
    setShowModalStatus(false)

    console.log(JSON.stringify(parameterPost(paymentCode?.payment_code)))

    setLoadingFull(true)
    JSONAxioPost(postURL('api_cohub_proses_setoran_cod', null), parameterPost(paymentCode?.payment_code),token)
        .then(respone => {
          const response = respone?.data;

          setLoadingFull(false);
          
          if (response?.statusCode == 1) {

            if(draft){
              navigation.navigate(Routers.SUCCESS_SCREEN, { title: 'Setoran Berhasil Disimpan ', desc: 'Setoran anda sudah berhasil di simpan ke dalam draft', titleButton: 'Kembali', groupArraySelection: originalArraySelection, totalPrice: totalPrice })
            } else {
              onpressProcessTranssaction(paymentCode, draft)
            }
            
          } else {
            setLoadingFull(false);
            cekError(response.statusCode, response.message);

          }
        })
        .catch(error => {
          setLoadingFull(false);
          cekError(2, null);

        });
  }

  const onpressProcessTranssaction=(paymentCode, draft)=>{
    setShowModalStatus(false)
    setLoadingFull(true)
    JSONAxioPost(postURL('api_cohub_kirim_bukti_setoran', null), parameterPost(paymentCode?.payment_code),token)
        .then(respone => {
          const response = respone?.data;

          setLoadingFull(false);
          
          if (response?.statusCode == 1) {

            if((paymentMethode?.category == 'Transfer Bank' || paymentMethode?.category == 'Virtual Account Bank') && tabFlag==3){
              navigation.navigate(Routers.SUCCESS_SCREEN, { title: 'Setoran Berhasil Diserahkan ', desc: 'Proses verifikasi pembayaran kurang dari 10 menit setelah pembayaran berhasil', titleButton: 'Kembali', groupArraySelection: originalArraySelection, totalPrice: totalPrice })
            }
            
          } else {
            setLoadingFull(false);
            cekError(response.statusCode, response.message);

          }
        })
        .catch(error => {
          setLoadingFull(false);
          cekError(2, null);

        });
  }


  const onpressOrder =(imageList, paymentCode, draft) =>{
    console.log(paymentCode)
    if (tabFlag == 2){
      if(!paymentCode?.category){
        
        cekError(2, "Silakan Pilih Methode Pembayaran Anda.");
        return
      }

      if (imageList.length <= 0 && paymentCode?.category === "Virtual Account Bank"){
        cekError(2, "Silakan Upload Bukti Pembayaran Anda.");
        return
      }
      
    }
 
    setShowModalStatus(false)

    setLoadingFull(true)
    JSONAxioPost(postURL(postUrl(draft), null), parameterPost(paymentCode),token)
        .then(respone => {
          const response = respone?.data;

          setLoadingFull(false);
          
          if (response?.statusCode == 1) {
            // if (tabFlag == 2){
            //   seIdSetoranCoHub(response?.result?.idSetoranCoHub)
            //   imageList.map((item, i) => {
            //     uploadImage(item.base64, response?.result?.idSetoranCoHub, originalArraySelection, (i+1),imageList)
            //   })
            // } else {
              navigation.navigate(Routers.SUCCESS_SCREEN, { title: 'Setoran berhasil Diserahkan', desc: 'Setoran anda sudah berhasil di serahkan', titleButton: 'Kembali', groupArraySelection: originalArraySelection, totalPrice: totalPrice })
            // }
            
          } else {
            setLoadingFull(false);
            cekError(response.statusCode, response.message);

          }
        })
        .catch(error => {
          setLoadingFull(false);
          cekError(2, null);

        });
  }

  const uploadImage =(image, idSetoranCoHub, originalArraySelection,index, imageList) =>{

    var parameter = {
      "idSetoranCoHub": idSetoranCoHub,
      "tipe": 1,
      "buktiFoto": image}

    setLoadingFull(true)
    JSONAxioPost(postURL("api_cohub_bukti_bayar", null), parameter,token)
        .then(respone => {
          const response = respone?.data;

          setLoadingFull(false);
          
          if (response?.statusCode == 1) {
            if (imageList.length == index) {
              navigation.navigate(Routers.SUCCESS_SCREEN, { title: 'Setoran berhasil Diserahkan', desc: 'Setoran anda sudah berhasil di serahkan', titleButton: 'Kembali', groupArraySelection: originalArraySelection, totalPrice: totalPrice })
            }
          } else {
            setLoadingFull(false);
            cekError(response.statusCode, response.message);

          }
        })
        .catch(error => {
          setLoadingFull(false);
          cekError(2, null);

        });
  }

  const onHideLispayment =() =>{
    setShowModalListPayment(false)
  }

  const onpressItem =(item) =>{
    
    setShowModalListPayment(false)
    setShowModalSetoranFoloni(true)
    setPaymentMethode(item)
  }

  

  const onShowLispayment =() =>{
    setShowModalSetoranFoloni(false)
    setShowModalListPayment(true)
  }

  const valueTitleTiga =(tabFlag,item)=>{
    if (tabFlag == 3){
      return item?.tanggalDibuat
    } else if (tabFlag == 4){
      return item?.tanggalDibuat
    } else if (tabFlag == 5){
      return item?.tanggalDibuat
    }  else if (tabFlag == 6){
      return item?.tanggalDibuat
    }
   }

  return (
    <SafeAreaView style={{ flex: 1, }}>
      <View style={{ flex: 1, backgroundColor: Colors.white }}>


        {<View style={{ backgroundColor: Colors.white, flexDirection: 'row', paddingBottom: Scale(0), alignItems: 'center', justifyContent: 'center' }}>

          <View style={{ flex: 0.1, justifyContent: 'center', paddingLeft: Scale(8), marginTop: Scale(16) }}>
            <TouchableOpacity
              onPress={goBack}>
              <Image
                style={[{ height: Scale(30), width: Scale(30), tintColor: Colors.primaryColorHub }]}
                source={getIcon('ic_arrow_left_line')}
                resizeMode='contain' />
            </TouchableOpacity>

          </View>

          <View style={{ flex: 1 }}>
            <TextInput
              style={{ marginTop: Scale(20) }}
              onChange={value => setSearch(value)}
              icon={'ic_search'}
              value={search}
              placeholder={'Cari Transaksi COD'}
              onPress={() => { getdataHubCohub(search, tabFlag) }}
              title={''}
              error={null}
            />
          </View>

        </View>}

        <TabLayout
          show={'readyToSend' != tabFlag ? true : false}
          title={title}
          titleType={titleType}
          openStatus={() => setShowStatus(true)}
          openType={() => setShowType(true)}
        />

        <View style={{ flex: 1 }}>

          <FlatList
            style={{ flex: 1, backgroundColor: Colors.greenWhite }}
            refreshing={loading}
            onRefresh={() => { getdataHubCohub(search, tabFlag) }}
            data={newsOrder.length == 0 ? [''] : newsOrder}
            renderItem={({ item, index }) =>
            (
              <View>
                {(newsOrder.length != 0) && <ItemOrder
                tabFlag = {tabFlag}
                checkBoxActive={checkSelection(item)}
                  onPressCheckBox = {(item) => onpressSelection(item)}
                  titleButtonDetil={'Ambil Pesanan'}
                  navigation={navigation}
                  key={index}
                  onPressSend={() => selectedItem(item)}
                  onPress={() => onPresHDetil(item)}
                  data={item} />}

                {(newsOrder.length == 0) && <View style={{ height: Metrics.screenHeight / 1.5, justifyContent: 'center', alignItems: 'center', paddingHorizontal: Scale(16) }}>

                  <Image
                    style={{ height: Scale(150), width: Scale(150) }}
                    source={getIcon('img_oops')}
                    resizeMode='contain' />

                  <Text style={{ fontSize: Scale(18), textAlign: 'center' }}>Maaf Anda belum ada transaksi apapun saat ini</Text>
                </View>}
              </View>
            )
            }
          />

          {arraySelection.length !== 0 && <View style={{ height: Scale(60), backgroundColor: Colors.gray, justifyContent:'center', }}>
            <View style={{ flexDirection: 'row', paddingHorizontal: Scale(8) }}>
              <View style={{ flex: 0.4, justifyContent:'center' }}>
                <Text style={[styles.text400, { color: Colors.black, fontSize: Scale(10) }]}>{'Total Nilai :'}</Text>
              </View>
              <View style={{ flex: 1, justifyContent:'center' }}>
                <Text style={[styles.text400, { color: Colors.red, fontSize: Scale(10) }]}>{"Rp "+ currency(totalPrice,"")}</Text>
              </View>

             <View style={{ flex: 1 }}>
                <Buttons
                  style={[{ backgroundColor: Colors.primaryColorHub, borderColor: Colors.primaryColorHub, borderWidth: Scale(1) }]}
                  styleTitle={{ color: Colors.white }}
                  onPress={() => onpressButton()}
                  switchAccount={true}
                  title={(titleButton()+" (" +arraySelection.length+")")} />
              </View>
            </View>
          </View>}
        </View>

        <ModalStatusReadyToSend
          isHubSend={route.params?.isHubSend}
          isCodCoHub={true}
          readySend={true}
          onPresStatus={(item) => selectSetTabFlag(item)}
          onClose={() => setShowStatus(false)}
          ShowStatus={showStatus} />

        <ModalConformationSendHub
          data={dataDetil}
          onPresButtonConfirm={(value) => onPresHubSendConfirm(value)}
          onCloses={() => setShowModalConfirm(false)}
          ShowComment={showModalConfirm}
          loading={(value) => setLoading(value)}
          cekError={(value1, value2) => cekError(value1, value2)}
        />

        <ModalSetoranCodHub
        tabFlag ={tabFlag != 2 ? true : false}
          totalPrice = {totalPrice}
          hubPencairan ={true}
          statusPengiriman={groupArraySelection}
          // status={detilDataMyCard?.status_proses}
          onPresButtonOrder={() => onpressOrder(false, false, false)}
          onPresButton={() => console.log("")}
          onCloses={() => setShowModalStatus(false)}
          ShowComment={showModalStatus}
          // showKonfirmation={detilDataMyCard?.status_tombol_konfirmasi}
          // showImage={(value) => { openImage(value) }}
          title={false} />
        <ModalSetoranCodFoloni
          navigation = {navigation}
          totalPrice={totalPrice}
          hubPencairan={true}
          statusPengiriman={groupArraySelection}
          paymentMethode={paymentMethode}
          onPresButtonOrder={(imageList, paymentCode) => onpressProcessTranssaction(paymentCode, true)}
          onPresButtonSaveDraft={(imageList, paymentCode) => onpressSaveDraft(paymentCode, true)}
          onPresButton={() => console.log("")}
          flagSaldo={isUseSaldo}
          nomorSetoranCohub={dataDetil?.idSetoranCohub}
          reasonCancel={dataDetil?.reason}
          createdDate={valueTitleTiga(tabFlag, items)}
          confirmationDate={dataDetil?.tanggalKonfirmasi}
          openPaymentMethode={() => onShowLispayment()}
          codeUnik={dataDetil?.codeUnik}
          listImage={dataDetil?.img_setoran ? dataDetil?.img_setoran : []}
          setorkanSebelum={dataDetil?.setorkanSebelum ? dataDetil?.setorkanSebelum : null}
          onCloses={() => {
            setShowModalSetoranFoloni(false)
            setIsUseSaldo(false)
            setPressDetil(true)
            setDataDetil(null)
            setPaymentMethode({ name: "Pilih Metode Pembayaran Untuk Setoran", icon: null, category: null, height: Scale(20), width: Scale(50) })
          }}
          ShowComment={showModalSetoranFoloni}
          isUseSaldo = {(focoSaldo) => setIsUseSaldo(focoSaldo)}
          // showKonfirmation={detilDataMyCard?.status_tombol_konfirmasi}
          // showImage={(value) => { openImage(value) }}
          tabFlag={tabFlag}
          title={false} />

        <ModalListPayment
          navigation={navigation}
          totalPrice={totalPrice}
          hubPencairan={true}
          statusPengiriman={groupArraySelection}
          onpressItem={(item) => onpressItem(item)}
          onPresButton={() => console.log("")}
          onCloses={() => onHideLispayment()}
          ShowComment={showModalListPayment}
          title={false} />

        <Loading
          visible={loadingFull} />

        <PopUp
          visible={warning}
          onPressButton={() => { actionButton() }}
          title={contentWarning?.title}
          desc={contentWarning?.desc}
          titleButton={contentWarning?.titleButton} />
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  button: {
    alignItems: 'center',
    backgroundColor: '#DDDDDD',
    padding: 10,
    width: 300,
    marginTop: 16,
  },
  imgRow: { height: Scale(90), width: Scale(90) },
  text400: { color: Colors.black, fontWeight: '400', fontSize: Scale(14) },
});
export default CodCoHub;